235:             $item = Get-Item -LiteralPath $path
236:             if ($null -eq $reader -or $created -ne $item.CreationTimeUtc -or $reader.BaseStream.Position -gt $item.Length) {
237:                 if ($null -ne $reader) { $reader.Dispose() }
238:                 $stream = [IO.File]::Open($path, [IO.FileMode]::Open, [IO.FileAccess]::Read,
239:                     ([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
240:                 $reader = New-Object IO.StreamReader($stream, [Text.Encoding]::UTF8)
241:                 $created = $item.CreationTimeUtc
242:                 if ($initial) {
243:                     $tail = New-Object 'Collections.Generic.Queue[string]'
244:                     while (-not $reader.EndOfStream) {
245:                         $tail.Enqueue($reader.ReadLine())
246:                         if ($tail.Count -gt 80) { [void]$tail.Dequeue() }
247:                     }
