251:             }
252:             while (-not $reader.EndOfStream) { Write-Host $reader.ReadLine() }
253:             Start-Sleep -Milliseconds 250
254:         }
255:     } finally { if ($null -ne $reader) { $reader.Dispose() } }
256: }
